<script setup>
/** * Page de connexion (Login) combinant l'arrière-plan esthétique (split image + blobs #01313E) * et les fonctionnalités complètes du formulaire. */
import { ref } from'vue'
import { useRouter } from'vue-router'
import { useAuthStore } from'../stores/auth'
import api from'../services/api'
import { Mail, Lock, Loader2, CheckCircle2, AlertCircle, X, Eye, EyeOff } from'lucide-vue-next' const router = useRouter()
const authStore = useAuthStore() const email = ref('')
const password = ref('')
const rememberMe = ref(false)
const showPassword = ref(false) // Modal"Mot de passe oublié / Lien par email"
const showResetModal = ref(false)
const resetEmail = ref('')
const resetLoading = ref(false)
const resetSuccess = ref(false)
const resetError = ref('') const handleLogin = async () => { const success = await authStore.login(email.value, password.value) if (success) { router.push('/dashboard') }
} const openResetModal = () => { resetEmail.value = email.value resetError.value ='' resetSuccess.value = false showResetModal.value = true
} const handleResetPassword = async () => { if (!resetEmail.value) { resetError.value ="Veuillez saisir votre adresse e-mail." return } resetLoading.value = true resetError.value ='' try { await api.post('auth/reinit-mdp/', { email: resetEmail.value }) resetSuccess.value = true } catch (err) { resetError.value = err.response?.data?.detail ||"Une erreur est survenue lors de l'envoi de l'e-mail." } finally { resetLoading.value = false }
}
</script> <template> <div class="min-h-screen flex flex-col lg:flex-row"> <!-- Section Image & Dégradé (Gauche) --> <div class="hidden lg:flex lg:w-1/2 relative bg-[#01313E] overflow-hidden"> <img src="/images/login-bg.png" alt="Sourcing Connect Team" class="absolute inset-0 w-full h-full object-cover opacity-90 transition-transform duration-1000 hover:scale-105" onerror="this.src='https://images.unsplash.com/photo-1522071820081-009f0129c71c?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80';" /> <div class="absolute inset-0"></div> <div class="absolute bottom-12 left-12 right-12 text-white z-10"> <h2 class="text-4xl font-bold mb-4 tracking-tight">Rejoignez Sourcing Connect</h2> <p class="text-lg text-white leading-relaxed"> Trouvez les meilleurs talents ou la meilleure formation avec notre plateforme intégrée de sourcing. </p> </div> </div> <!-- Section Formulaire avec fond clair et motif (Droite) --> <div class="flex-1 flex items-center justify-center bg-[#FFFFFF] py-12 px-4 sm:px-6 lg:px-8 relative overflow-hidden" > <!-- Blobs animés Simplon --> <div class="absolute -top-40 -right-40 w-96 h-96 bg-[#E30046]/10 rounded-full filter opacity-50" ></div> <div class="absolute -bottom-40 -left-40 w-96 h-96 bg-[#01313E]/15 rounded-full filter opacity-60 animation-delay-2000" ></div> <!-- Carte du formulaire --> <div class="max-w-md w-full bg-white rounded-3xl border border-[#01313E]/10 p-8 sm:p-10 space-y-6 relative z-10"> <!-- En-tête / Logo --> <div class="flex flex-col items-center text-center"> <img src="/images/logo1.png" alt="Simplon Sourcing Logo" class="h-16 w-auto mb-3 object-contain" onerror="this.style.display='none'; document.getElementById('fallback-title').style.display='block';" /> <h2 id="fallback-title"class="hidden text-center text-2xl font-extrabold text-[#01313E] tracking-tight"> Simplon<span class="text-[#E30046]">Sourcing</span> </h2> <h3 class="text-2xl font-extrabold text-[#01313E] tracking-tight mt-1">Connexion à votre espace</h3> <p class="text-xs text-[#01313E]/60 font-semibold mt-1">Plateforme Officielle Simplon Sourcing</p> </div> <!-- Formulaire de Connexion --> <form @submit.prevent="handleLogin"class="space-y-4 pt-1"> <!-- Champ Email --> <div class="space-y-1.5"> <label for="email"class="block text-xs font-bold text-[#01313E]">Email</label> <div class="relative"> <Mail class="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-[#01313E]/60"/> <input id="email" type="email" v-model="email" required placeholder="nom@simplon.co" class="w-full pl-10 pr-4 py-2.5 rounded-xl border border-[#01313E]/10 text-sm focus:outline-none focus:ring-2 focus:focus:border-[#E30046] transition-all placeholder:text-[#01313E]/60 bg-white" /> </div> </div> <!-- Champ Mot de passe avec lien aligné à droite et icône œil --> <div class="space-y-1.5"> <div class="flex items-center justify-between"> <label for="password"class="block text-xs font-bold text-[#01313E]">Mot de passe</label> <button type="button" @click="openResetModal()" class="text-xs font-semibold text-[#01313E]/60 hover:text-[#E30046] transition-colors" > Mot de passe oublié ? </button> </div> <div class="relative"> <Lock class="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-[#01313E]/60"/> <input id="password" :type="showPassword ?'text' :'password'" v-model="password" required placeholder="••••••••" class="w-full pl-10 pr-10 py-2.5 rounded-xl border border-[#01313E]/10 text-sm focus:outline-none focus:ring-2 focus:focus:border-[#E30046] transition-all bg-white" :class="{'border-[#E30046] ring-2': authStore.error }" /> <button type="button" @click="showPassword = !showPassword" class="absolute right-3 top-1/2 -translate-y-1/2 text-[#01313E]/60 hover:text-[#01313E]/80 focus:outline-none p-1 transition-colors" :title="showPassword ?'Masquer le mot de passe' :'Afficher le mot de passe'" > <EyeOff v-if="showPassword"class="w-4 h-4"/> <Eye v-else class="w-4 h-4"/> </button> </div> <!-- Message d'erreur rouge directement sous le mot de passe --> <p v-if="authStore.error"class="text-xs text-[#E30046] font-semibold pt-0.5"> {{ authStore.error.toLowerCase().includes('identifiant') || authStore.error.toLowerCase().includes('invalide') ?'Mot de passe incorrect' : authStore.error }} </p> </div> <!-- Case Se souvenir de moi --> <div class="flex items-center pt-1"> <input id="remember-me" type="checkbox" v-model="rememberMe" class="h-4 w-4 text-[#01313E] focus:border-[#01313E]/10 rounded" /> <label for="remember-me"class="ml-2.5 block text-xs font-semibold text-[#01313E]/80"> Se souvenir de moi </label> </div> <!-- Bouton Se connecter --> <button type="submit" :disabled="authStore.loading" class="w-full py-3.5 px-4 bg-[#E30046] hover:bg-[#C7003D] active:scale-[0.99] text-white text-sm font-extrabold rounded-xl transition-all duration-200 -[#E30046]/30 flex items-center justify-center gap-2" > <Loader2 v-if="authStore.loading"class="w-4 h-4 animate-spin"/> <span>Se connecter</span> </button> <!-- État"Traitement en cours..."lorsque la connexion est en cours --> <div v-if="authStore.loading" class="w-full py-3 px-4 bg-white text-[#01313E]/80 text-xs font-semibold rounded-xl flex items-center justify-center gap-2 animate-pulse" > <Loader2 class="w-4 h-4 animate-spin text-[#01313E]/80"/> <span>Traitement en cours...</span> </div> <!-- Séparateur"OU CONTINUER AVEC"--> <div class="relative my-5"> <div class="absolute inset-0 flex items-center"> <div class="w-full border-t border-[#01313E]/10"></div> </div> <div class="relative flex justify-center text-xs uppercase"> <span class="bg-white px-3 text-[#01313E]/60 font-semibold tracking-wider text-[11px]"> ou continuer avec </span> </div> </div> <!-- Bouton : Recevoir un lien de connexion par email --> <button type="button" @click="openResetModal()" class="w-full py-3 px-4 border border-[#01313E]/10 bg-white hover:bg-[#FFFFFF] text-[#01313E] text-xs font-bold rounded-xl transition-all flex items-center justify-center gap-2" > <Mail class="w-4 h-4 text-[#01313E]"/> <span>Recevoir un lien de connexion par email</span> </button> <!-- Lien candidat --> <div class="text-center pt-3 border-t border-[#01313E]/10"> <router-link to="/" class="text-xs font-bold text-[#E30046] hover:text-[#a8002a] transition-colors" > Vous souhaitez postuler ? Découvrir nos campagnes </router-link> </div> </form> </div> </div> <!-- Modal Réinitialisation / Lien Email --> <div v-if="showResetModal" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#01313E]/60 transition-opacity" > <div class="bg-white rounded-3xl max-w-md w-full p-6 sm:p-8 space-y-6 border border-[#01313E]/10 relative"> <button @click="showResetModal = false" class="absolute top-5 right-5 text-[#01313E]/60 hover:text-[#01313E]/80 p-1" > <X class="w-5 h-5"/> </button> <div class="text-center space-y-2"> <div class="w-12 h-12 bg-white text-[#E30046] rounded-2xl flex items-center justify-center mx-auto mb-3"> <Mail class="w-6 h-6"/> </div> <h3 class="text-lg font-bold text-[#01313E]">Réinitialisation / Connexion par e-mail</h3> <p class="text-xs text-[#01313E]/60 max-w-xs mx-auto"> Saisissez votre e-mail pour recevoir un lien de connexion ou de réinitialisation sécurisé. </p> </div> <div v-if="resetSuccess"class="bg-white border border-[#01313E] text-[#01313E] p-4 rounded-2xl text-xs space-y-2"> <div class="flex items-center gap-2 font-bold text-[#01313E]"> <CheckCircle2 class="w-4 h-4 text-[#01313E] flex-shrink-0"/> <span>E-mail envoyé avec succès !</span> </div> <p class="text-[#01313E]"> Si un compte correspond à cette adresse e-mail, vous recevrez sous peu votre lien sécurisé. </p> <button @click="showResetModal = false" class="w-full mt-3 py-2 bg-[#01313E] text-white rounded-xl font-bold hover:bg-[#01313E] transition-colors" > Fermer </button> </div> <form v-else @submit.prevent="handleResetPassword"class="space-y-4"> <div v-if="resetError"class="bg-white border border-[#E30046] text-[#E30046] p-3 rounded-xl text-xs flex items-center gap-2"> <AlertCircle class="w-4 h-4 text-[#E30046] flex-shrink-0"/> <span>{{ resetError }}</span> </div> <div> <label class="block text-xs font-bold text-[#01313E] mb-1">Votre adresse e-mail</label> <input type="email" v-model="resetEmail" required placeholder="nom@simplon.co" class="w-full px-4 py-2.5 border border-[#01313E]/10 rounded-xl text-sm focus:outline-none focus:ring-2 focus:focus:border-[#E30046]" /> </div> <div class="flex gap-3 pt-2"> <button type="button" @click="showResetModal = false" class="flex-1 py-2.5 border border-[#01313E]/10 text-[#01313E]/80 rounded-xl text-xs font-semibold hover:bg-white transition-colors" > Annuler </button> <button type="submit" :disabled="resetLoading" class="flex-1 py-2.5 bg-[#E30046] hover:bg-[#C7003D] text-white rounded-xl text-xs font-bold transition-colors flex items-center justify-center gap-1.5 -[#E30046]/20" > <Loader2 v-if="resetLoading"class="w-3.5 h-3.5 animate-spin"/> <span>{{ resetLoading ?'Envoi...' :'Envoyer le lien' }}</span> </button> </div> </form> </div> </div> </div>
</template> <style scoped>
@keyframes blob { 0% { transform: translate(0px, 0px) scale(1); } 33% { transform: translate(30px, -40px) scale(1.08); } 66% { transform: translate(-20px, 20px) scale(0.95); } 100% { transform: translate(0px, 0px) scale(1); }
}
. { animation: blob 8s infinite ease-in-out;
